// DesignLinkedList
class DesignLinkedList {private static class Node{int v;Node n;Node(int x){v=x;}}private Node head;private int size;public int get(int i){if(i<0||i>=size)return -1;Node p=head;while(i-->0)p=p.n;return p.v;}public void addAtHead(int x){Node p=new Node(x);p.n=head;head=p;size++;}public void addAtTail(int x){addAtIndex(size,x);}public void addAtIndex(int i,int x){if(i>size)return;if(i<=0){addAtHead(x);return;}Node p=head;for(int j=1;j<i;j++)p=p.n;Node n=new Node(x);n.n=p.n;p.n=n;size++;}public void deleteAtIndex(int i){if(i<0||i>=size)return;if(i==0)head=head.n;else{Node p=head;for(int j=1;j<i;j++)p=p.n;p.n=p.n.n;}size--;}}
